// Fission products, chapter 3 "TRISO kernel" (lessons 10-28): the small
// models behind the demos, shared by the pages, kernel-worker.js and
// check-fission.js (node). Pure functions, no DOM. Data from kernel-data.js
// (generated by crates/dhoby-ghaut/examples/lesson_triso_kernel).
//
// Booth's sphere (TRISO-ATOPS port in boon-lay, TRISO_ATOPS_DERIVATION.md
// sections 3-5a): fractional release of a stable species
//   f(x) = 1 - (6/pi^2) sum_n exp(-n^2 pi^2 x) / n^2,  x = D t / a^2,
// and the steady release-to-birth ratio of a decaying one
//   R/B = (3/mu)(coth mu - 1/mu),  mu = sqrt(lambda a^2 / D).
// check-fission.js checks both against boon-lay's own values in
// kernel-data.js. Everything labelled ILLUSTRATIVE on a page (grain sizes,
// the coarsening and pore models) is a teaching model, not data.
(function () {
  "use strict";
  var root = typeof window !== "undefined" ? window : self;

  function boothF(x) {
    if (x <= 0) return 0;
    // Short times: the series converges slowly; use the closed form there
    // (the derivation's short-time expansion) where it is exact to 1e-12.
    if (x < 1e-4) return 6 * Math.sqrt(x / Math.PI) - 3 * x;
    var s = 0;
    for (var n = 1; n <= 2000; n++) {
      var t = Math.exp(-n * n * Math.PI * Math.PI * x) / (n * n);
      s += t;
      if (t < 1e-17) break;
    }
    return 1 - 6 / (Math.PI * Math.PI) * s;
  }
  function boothRB(mu) {
    if (mu < 1e-3) return 1 - mu * mu / 15;
    return 3 / mu * (1 / Math.tanh(mu) - 1 / mu);
  }

  // Log-linear interpolation of a D curve (grid tC [°C], values d) at tC.
  function dAt(tC, grid, d) {
    if (tC <= grid[0]) return d[0];
    for (var i = 1; i < grid.length; i++) if (tC <= grid[i]) {
      var u = (tC - grid[i - 1]) / (grid[i] - grid[i - 1]);
      return Math.exp(Math.log(d[i - 1]) * (1 - u) + Math.log(d[i]) * u);
    }
    return d[d.length - 1];
  }

  // A set of grain spheres: radii [m] and their temperatures [°C]; each is
  // a Booth sphere at its own D(T); births are uniform per volume, so the
  // total is the volume-weighted sum. Returns the released fraction at t.
  function manySpheres(radii, tCs, t, Dfun) {
    var num = 0, den = 0;
    for (var i = 0; i < radii.length; i++) {
      var a = radii[i], v = a * a * a, D = Dfun(tCs[i]);
      num += v * boothF(D * t / (a * a));
      den += v;
    }
    return num / den;
  }

  // Lognormal grain radii (ILLUSTRATIVE): n radii about `median` with
  // log-width `sigma`, by inverse-CDF on a regular probability grid (so the
  // set is deterministic).
  function lognormalRadii(median, sigma, n) {
    var out = [];
    for (var i = 0; i < n; i++) {
      var p = (i + 0.5) / n;
      out.push(median * Math.exp(sigma * Math.SQRT2 * erfinv(2 * p - 1)));
    }
    return out;
  }
  function erfinv(x) {
    // Giles (2010) single-precision approximation, then two Newton steps.
    var w = -Math.log((1 - x) * (1 + x)), p;
    if (w < 5) { w -= 2.5; p = 2.81022636e-08; p = 3.43273939e-07 + p * w; p = -3.5233877e-06 + p * w; p = -4.39150654e-06 + p * w; p = 0.00021858087 + p * w; p = -0.00125372503 + p * w; p = -0.00417768164 + p * w; p = 0.246640727 + p * w; p = 1.50140941 + p * w; }
    else { w = Math.sqrt(w) - 3; p = -0.000200214257; p = 0.000100950558 + p * w; p = 0.00134934322 + p * w; p = -0.00367342844 + p * w; p = 0.00573950773 + p * w; p = -0.0076224613 + p * w; p = 0.00943887047 + p * w; p = 1.00167406 + p * w; p = 2.83297682 + p * w; }
    var y = p * x;
    for (var k = 0; k < 2; k++) y -= (erf(y) - x) / (2 / Math.sqrt(Math.PI) * Math.exp(-y * y));
    return y;
  }
  function erf(x) {
    // Abramowitz & Stegun 7.1.26 is too coarse for the Newton step; use the
    // series / continued fraction split.
    var ax = Math.abs(x), s;
    if (ax < 2.5) {
      var sum = ax, term = ax, n = 0;
      while (Math.abs(term) > 1e-17 * Math.abs(sum) && n < 200) { n++; term *= -ax * ax / n; sum += term / (2 * n + 1); }
      s = 2 / Math.sqrt(Math.PI) * sum;
    } else {
      var f = 0;
      for (var m = 60; m >= 1; m--) f = m / 2 / (ax + f);
      s = 1 - Math.exp(-ax * ax) / Math.sqrt(Math.PI) / (ax + f);
    }
    return x < 0 ? -s : s;
  }

  // Seedable generator (mulberry32), as in hop-physics.js.
  function rng(seed) {
    var a = seed >>> 0;
    return function () {
      a = (a + 0x6D2B79F5) >>> 0;
      var t = a;
      t = Math.imul(t ^ (t >>> 15), t | 1);
      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }
  function gauss(r) { return Math.sqrt(-2 * Math.log(1 - r())) * Math.cos(2 * Math.PI * r()); }

  // Random walk out of a unit sphere: n atoms born uniformly, Gaussian steps
  // of variance 2 D dt per axis in reduced units (D = 1, a = 1), until the
  // reduced time x. Returns the escaped fraction and a few paths to draw.
  function walkSphere(n, x, steps, seed, keep) {
    var r = rng(seed), dt = x / steps, sd = Math.sqrt(2 * dt), out = 0, paths = [];
    for (var i = 0; i < n; i++) {
      var px, py, pz;
      do { px = 2 * r() - 1; py = 2 * r() - 1; pz = 2 * r() - 1; } while (px * px + py * py + pz * pz > 1);
      var path = i < (keep || 0) ? [[px, py]] : null, gone = false;
      for (var s = 0; s < steps; s++) {
        px += sd * gauss(r); py += sd * gauss(r); pz += sd * gauss(r);
        if (path) path.push([px, py]);
        if (px * px + py * py + pz * pz >= 1) { gone = true; break; }
      }
      if (gone) out++;
      if (path) paths.push(path);
    }
    return { f: out / n, paths: paths };
  }

  // Fraction of fragments born uniformly in a sphere of radius a that leave
  // it in a straight line of length mu (isotropic): the recoil "skin".
  // Computed here by Monte Carlo (no formula typed); n samples.
  function recoilEscape(muOverA, n, seed) {
    var r = rng(seed), out = 0;
    for (var i = 0; i < n; i++) {
      var x, y, z;
      do { x = 2 * r() - 1; y = 2 * r() - 1; z = 2 * r() - 1; } while (x * x + y * y + z * z > 1);
      var c = 2 * r() - 1, ph = 2 * Math.PI * r(), s = Math.sqrt(1 - c * c);
      x += muOverA * s * Math.cos(ph); y += muOverA * s * Math.sin(ph); z += muOverA * c;
      if (x * x + y * y + z * z > 1) out++;
    }
    return out / n;
  }

  // A 2D Potts model (ILLUSTRATIVE grain coarsening): q orientations on an
  // L x L periodic grid; a site takes a random neighbour's orientation if
  // that does not raise the boundary count, or with exp(-dE/kT') if it does.
  function pottsInit(L, q, seed) {
    var r = rng(seed), g = new Int16Array(L * L);
    for (var i = 0; i < g.length; i++) g[i] = (r() * q) | 0;
    return { L: L, q: q, g: g, r: r };
  }
  function pottsSweep(s, kT) {
    var L = s.L, g = s.g, r = s.r, N = L * L;
    for (var k = 0; k < N; k++) {
      var i = (r() * N) | 0, x = i % L, y = (i / L) | 0;
      var nb = [((y * L) + (x + 1) % L), (y * L + (x + L - 1) % L), (((y + 1) % L) * L + x), (((y + L - 1) % L) * L + x)];
      var cand = g[nb[(r() * 4) | 0]];
      if (cand === g[i]) continue;
      var e0 = 0, e1 = 0;
      for (var j = 0; j < 4; j++) { if (g[nb[j]] !== g[i]) e0++; if (g[nb[j]] !== cand) e1++; }
      var dE = e1 - e0;
      if (dE <= 0 || (kT > 0 && r() < Math.exp(-dE / kT))) g[i] = cand;
    }
  }
  // Mean grain area: sites per distinct connected region is costly; use
  // boundary density instead (fraction of bonds across a boundary), whose
  // inverse grows like the grain size.
  function boundaryFraction(s) {
    var L = s.L, g = s.g, b = 0;
    for (var y = 0; y < L; y++) for (var x = 0; x < L; x++) {
      var i = y * L + x;
      if (g[i] !== g[y * L + (x + 1) % L]) b++;
      if (g[i] !== g[((y + 1) % L) * L + x]) b++;
    }
    return b / (2 * L * L);
  }

  root.KernelPhysics = {
    boothF: boothF, boothRB: boothRB, dAt: dAt, manySpheres: manySpheres, lognormalRadii: lognormalRadii,
    erf: erf, erfinv: erfinv, rng: rng, walkSphere: walkSphere, recoilEscape: recoilEscape,
    pottsInit: pottsInit, pottsSweep: pottsSweep, boundaryFraction: boundaryFraction
  };
})();
